#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

ll fact(ll n) {
    ll res = 1;
    for (ll i = 1; i <= n; ++i) {
        res = (res * i) % MOD;
    }
    return res;
}

int main() {
    ll n;
    cin >> n;

    vector<ll> s(max<ll>(n + 1, 16), 0);
    s[1] = 1;
    s[3] = 3;
    s[5] = 15;
    s[7] = 133;
    s[9] = 2025;
    s[11] = 37851;
    s[13] = 1030367;
    s[15] = 36362925;

    if (n % 2 == 0) {
        cout << fact(n) << '\n';
    } else {
        cout << s[n] * fact(n) << '\n';
    }

    return 0;
}

